12	func customerKey(c store.Customer) cursor { return cursor{T: c.CreatedAt, ID: c.ID} }
13	
14	// listCustomers lists the organization's customers, oldest first: all of them, those matching ?q= (name or email contains
15	// it, ignoring case), or the one with exactly ?email=.
16	func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
17		pg, ok := parsePage(w, r)
18		if !ok {
19			return
20		}
21		q := r.URL.Query()
22		var cs []store.Customer
23		switch {
24		case q.Get("email") != "":
25			cs = []store.Customer{}
26			if c, ok := s.store.FindCustomerByEmail(p.OrgID, q.Get("email")); ok {
27				cs = append(cs, c)
28			}
29		case q.Get("q") != "":
30			cs = s.store.SearchCustomers(p.OrgID, q.Get("q"))
31		default:
32			cs = s.store.Customers(p.OrgID)
33		}
34		items, next := pageOf(cs, customerKey, pg)
35		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
36	}
