38	func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
39		var in struct {
40			Name                 string            `json:"name"`
41			Email                string            `json:"email"`
42			DefaultPaymentMethod string            `json:"default_payment_method"`
43			Metadata             map[string]string `json:"metadata"`
44		}
45		if !decode(w, r, &in) {
46			return
47		}
48		c, err := s.store.CreateCustomer(p.OrgID, in.Name, in.Email, s.clock.Now())
49		if err != nil {
50			s.storeError(w, err)
51			return
52		}
53		if in.DefaultPaymentMethod != "" || len(in.Metadata) > 0 {
54			c, err = s.store.UpdateCustomer(p.OrgID, c.ID, func(c *store.Customer) error {
55				c.DefaultPaymentMethod, c.Metadata = in.DefaultPaymentMethod, in.Metadata
56				return nil
57			})
58			if err != nil {
59				_ = s.store.DeleteCustomer(p.OrgID, c.ID)
60				s.storeError(w, err)
61				return
62			}
63		}
64		s.publish(r.Context(), p.OrgID, "customer.created", c)
65		writeJSON(w, http.StatusCreated, c)
66	}
67	
68	func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
69		c, ok := s.store.Customer(p.OrgID, r.PathValue("id"))
70		if !ok {
71			writeError(w, http.StatusNotFound, "not_found", "no such customer")
72			return
73		}
74		writeJSON(w, http.StatusOK, c)
75	}
76	
77	func (s *Server) updateCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
78		var in struct {
79			Name                 *string            `json:"name"`
80			Email                *string            `json:"email"`
81			DefaultPaymentMethod *string            `json:"default_payment_method"`
82			Metadata             *map[string]string `json:"metadata"`
83		}
84		if !decode(w, r, &in) {
85			return
86		}
87		c, err := s.store.UpdateCustomer(p.OrgID, r.PathValue("id"), func(c *store.Customer) error {
88			if in.Name != nil {
89				c.Name = *in.Name
90			}
91			if in.Email != nil {
92				c.Email = *in.Email
93			}
94			if in.DefaultPaymentMethod != nil {
95				c.DefaultPaymentMethod = *in.DefaultPaymentMethod
96			}
97			if in.Metadata != nil {
98				c.Metadata = *in.Metadata
99			}
100			return nil
101		})
102		if err != nil {
103			s.storeError(w, err)
104			return
105		}
106		s.publish(r.Context(), p.OrgID, "customer.updated", c)
107		writeJSON(w, http.StatusOK, c)
108	}
109	
110	func (s *Server) deleteCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
111		id := r.PathValue("id")
112		if err := s.store.DeleteCustomer(p.OrgID, id); err != nil {
113			s.storeError(w, err)
114			return
115		}
116		s.publish(r.Context(), p.OrgID, "customer.deleted", map[string]string{"id": id})
117		w.WriteHeader(http.StatusNoContent)
118	}
119	
120	// exportCustomers answers the organization's customers as CSV, oldest first.
121	func (s *Server) exportCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
122		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
123		w.Header().Set("Content-Disposition", `attachment; filename="customers.csv"`)
124		cw := csv.NewWriter(w)
125		cw.UseCRLF = true
126		_ = cw.Write([]string{"id", "name", "email", "created_at"})
127		for _, c := range s.store.Customers(p.OrgID) {
128			_ = cw.Write([]string{c.ID, c.Name, c.Email, c.CreatedAt.UTC().Format(time.RFC3339)})
129		}
130		cw.Flush()
131	}
