338	// RevokeAPIKey stops a key from working.
339	func (s *Store) RevokeAPIKey(orgID, id string, now time.Time) (APIKey, error) {
340		s.mu.Lock()
341		defer s.mu.Unlock()
342		k, ok := s.apiKeys[id]
343		if !ok || k.OrgID != orgID {
344			return APIKey{}, ErrNotFound
345		}
346		if k.RevokedAt == nil {
347			t := now.UTC()
