276	// ---- API keys
277	
278	// CreateAPIKey gives a member a new API key.
279	func (s *Store) CreateAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		return s.createAPIKey(orgID, userID, name, now)
