		t.Fatalf("subscription for deleted customer: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.ID != jane.ID || !inv.Customer.Deleted {
		t.Fatalf("invoice customer = %+v", inv.Customer)
