	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+taker.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}

	// After 30 days a deletion cannot be undone, and once purged the invoice no longer names the customer.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("purged %d, want 1", n)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer != nil {
		t.Fatalf("purged customer still on the invoice: %+v", inv.Customer)
	}
}

