func TestSoftDeleteCustomer(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	john := e.CreateCustomer(e.Acme, "John", "john@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}, &sub)
	var inv struct {
		ID       string `json:"id"`
		Customer *struct {
			ID      string `json:"id"`
			Email   string `json:"email"`
			Deleted bool   `json:"deleted"`
		} `json:"customer"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 500}}}, &inv)

	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "has_active_subscriptions" {
		t.Fatalf("delete with an active subscription: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, nil, &sub)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)

	if r := e.Do("GET", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("get deleted: %s", r)
	}
	if r := e.Do("PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]any{"name": "Janet"}); r.Code != http.StatusNotFound {
		t.Fatalf("patch deleted: %s", r)
	}
	if r := e.Do("DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("delete deleted: %s", r)
	}
	for _, path := range []string{"/v1/customers", "/v1/customers?q=jane", "/v1/customers?email=jane@example.com"} {
		var page struct {
			Items []store.Customer `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &page)
		if len(page.Items) != map[bool]int{true: 0, false: 1}[strings.Contains(path, "jane")] && len(page.Items) != 1 && path == "/v1/customers" {
			t.Fatalf("%s = %+v", path, page.Items)
		}
		for _, c := range page.Items {
			if c.ID == jane.ID {
				t.Fatalf("%s lists the deleted customer", path)
			}
		}
	}
	rows, err := csv.NewReader(strings.NewReader(string(e.MustDo(http.StatusOK, "GET", "/v1/customers/export.csv", e.Acme.Key, nil, nil).Body))).ReadAll()
	if err != nil || len(rows) != 2 || rows[1][0] != john.ID {
		t.Fatalf("csv = %v, %v", rows, err)
	}
	if r := e.Do("POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1}}}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("invoice for deleted customer: %s", r)
	}
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": p.ID}); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("subscription for deleted customer: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer == nil || inv.Customer.ID != jane.ID || !inv.Customer.Deleted {
		t.Fatalf("invoice customer = %+v", inv.Customer)
	}

	// Jane's address is free again, so a new customer takes it; then Jane cannot be restored until that one is gone.
	taker := e.CreateCustomer(e.Acme, "Jane 2", "JANE@example.com")
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("restore with the email in use: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+taker.ID, e.Acme.Key, nil, nil)
	var restored store.Customer
	e.MustDo(http.StatusOK, "POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil, &restored)
	if restored.ID != jane.ID || restored.DeletedAt != nil {
		t.Fatalf("restored = %+v", restored)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore a customer that is not deleted: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore through another org: %s", r)
	}

	// After 30 days a deletion cannot be undone, and once purged the invoice no longer names the customer.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+jane.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+jane.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("purged %d, want 1", n)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &inv)
	if inv.Customer != nil {
		t.Fatalf("purged customer still on the invoice: %+v", inv.Customer)
	}
}

